mapper.select:
SELECT u.id AS id, u.username AS username, u.nickname AS nickname, u.avatar AS avatar, u.school AS school, u.campus AS campus, u.role AS role, u.status AS status, u.credit_score AS creditScore, u.created_at AS createdAt, u.disabled_at AS disabledAt FROM t_user u WHERE u.deleted = 0
AND (u.username LIKE CONCAT('%', #{q.keyword}, '%') OR u.nickname LIKE CONCAT('%', #{q.keyword}, '%'))
AND u.role = #{q.role}
AND u.status = #{q.status}
ORDER BY u.created_at DESC, u.id DESC
